mapper.sql:
WITH ranges AS (
 SELECT sku_id,quantity,occupy_start_date, AS effective_end_date
 FROM inventory_reservation WHERE sku_id IN
 #{item}
 AND sn_id IS NULL AND reservation_status IN ('held','paid_locked','renting','overdue_holding','disputed_holding')
), events AS (
 SELECT sku_id,GREATEST(occupy_start_date,#{startDate}) AS day,CAST(quantity AS DECIMAL(30,0)) AS delta
 FROM ranges WHERE occupy_start_date<=#{endDate} AND effective_end_date>=#{startDate}
 UNION ALL
 SELECT sku_id,DATE_ADD(NULLIF(effective_end_date,CAST('9999-12-31' AS DATE)),INTERVAL 1 DAY),-CAST(quantity AS DECIMAL(30,0))
 FROM ranges WHERE occupy_start_date<=#{endDate} AND effective_end_date>=#{startDate} AND effective_end_date<#{endDate}
), daily AS (SELECT sku_id,day,SUM(delta) delta FROM events GROUP BY sku_id,day), running AS (
 SELECT sku_id,SUM(delta) OVER(PARTITION BY sku_id ORDER BY day ROWS UNBOUNDED PRECEDING) occupied FROM daily
), peaks AS (SELECT sku_id,MAX(occupied) peak FROM running GROUP BY sku_id)
